insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('js-fonctions', 'javascript', 'Fonctions', 'Fonction classique ou fléchée', 'Déclarer un comportement réutilisable et comprendre les différences de this et de construction.', '["function","arrow function","paramètre","return","this","callback"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Deux syntaxes","langage":"JavaScript","contenu":"function additionner(a, b = 0) {\n  return a + b;\n}\n\nconst doubler = (nombre) => nombre * 2;\n\nadditionner(4, 3); // 7\ndoubler(5);        // 10","legende":""},{"type":"decomposition","titre":"Anatomie","elements":[{"terme":"additionner","explication":"nom utilisé pour appeler la fonction et lire les traces d’erreur."},{"terme":"(a, b = 0)","explication":"paramètres ; b possède une valeur par défaut si l’argument est undefined."},{"terme":"return","explication":"termine l’appel et fournit une valeur au code appelant."},{"terme":"(nombre) => nombre * 2","explication":"fonction fléchée avec retour implicite de l’expression."}]},{"type":"comparaison","titre":"Conséquences","colonnes":["Aspect","function","=>"],"lignes":[["this","Dépend de l’appel","Capturé lexicalement"],["new","Possible si constructible","Impossible"],["arguments","Objet arguments local","Pas d’objet arguments local"],["Callbacks courts","Correct","Souvent plus lisible"]]},{"type":"alerte","variante":"erreur","titre":"Erreur fréquente","contenu":"Une flèche avec accolades ne retourne rien automatiquement : const doubler = n => { n * 2 } renvoie undefined. Ajouter return ou retirer les accolades."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"MDN — Fonctions","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Guide/Functions"}]},{"type":"texte","titre":"Explication approfondie","contenu":"JavaScript orchestre des données et des actions. Séparez transformation pure, accès au monde 