insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-grep-rg-find', 'shell', 'Recherche', 'grep, rg et find : retrouver une information', 'Chercher un texte ou un fichier dans un projet sans parcourir chaque dossier à la main.', '["grep","rg","ripgrep","find","recherche"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Rechercher dans un projet","langage":"Bash","contenu":"grep -R \"app.get\" .              # grep récursif dans le dossier courant\nrg \"addEventListener\" src/        # ripgrep, rapide et lisible\nfind . -name \"*.js\" -type f        # trouver les fichiers JavaScript\nrg -n \"TODO|FIXME\" .               # afficher aussi les numéros de ligne","legende":""},{"type":"decomposition","titre":"Décomposition de rg","elements":[{"terme":"rg","explication":"outil de recherche moderne (ripgrep), souvent installé séparément."},{"terme":"\"addEventListener\"","explication":"motif recherché ; les guillemets protègent les espaces et caractères spéciaux."},{"terme":"src/","explication":"dossier limité à inspecter, au lieu de tout le projet."},{"terme":"-n","explication":"option qui ajoute le numéro de ligne dans le résultat."}]},{"type":"alerte","variante":"attention","titre":"Outil optionnel","contenu":"rg n’est pas présent sur toutes les machines. grep et find sont plus universels ; installez ripgrep seulement si vous le souhaitez."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"ripgrep — guide","url":"https://github.com/BurntSushi/ripgrep"},{"label":"GNU grep","url":"https://www.gnu.org/software/grep/manual/grep.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « grep, rg et find : retrouver une information », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : grep, rg et find : retrouver une information","langage":"Bash","contenu":"grep -R \"app.get\" .              # grep récursif dans le dossier courant\nrg \"addEventListener\" src/        # ripgrep, rapide et lisible\nfind . -name \"*.js\" -type f        # trouver les fichiers JavaScript\nrg -n \"TODO|FIXME\" .               # afficher aussi les numéros de ligne","legende":"Leçon « grep, rg et find : retrouver une information ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « grep, rg et find : retrouver une information » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « grep, rg et find : retrouver une information » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « grep, rg et find : retrouver une information » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["shell-cat-less-head-tail","shell-pipes-redirections","git-cycle"]'::jsonb, 77);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-pipes-redirections', 'shell', 'Combiner', 'Pipes, redirections et codes de sortie', 'Relier des commandes et enregistrer leur résultat pour créer de petits workflows.', '["pipe","redirection","stdin","stdout","&&","||"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Enchaîner des commandes","langage":"Bash","contenu":"npm run check > verification.txt       # écrire la sortie dans un fichier\ncat package.json | grep \"scripts\"    # envoyer la sortie de cat à grep\nmkdir build && cd build                 # cd seulement si mkdir réussit\nnode app.js || echo \"Le serveur a échoué\" # action si erreur","legende":""},{"type":"decomposition","titre":"Symboles essentiels","elements":[{"terme":">","explication":"redirige la sortie et remplace le fichier cible."},{"terme":">>","explication":"ajoute à la fin sans effacer le contenu existant."},{"terme":"|","explication":"envoie la sortie standard d’une commande vers l’entrée de la suivante."},{"terme":"&& / ||","explication":"exécute selon le code de sortie : succès ou échec."}]},{"type":"texte","titre":"Code de sortie","contenu":"Une commande termine généralement avec 0 en cas de réussite et une autre valeur en cas d’erreur. Le shell peut donc décider de continuer ou de lancer une solution de repli."},{"type":"alerte","variante":"erreur","titre":"Écraser un fichier","contenu":"La redirection > remplace le contenu. Utilisez >> si vous voulez ajouter, ou vérifiez le nom du fichier avant d’exécuter."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"Bash — Pipelines","url":"https://www.gnu.org/software/bash/manual/html_node/Pipelines.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Pipes, redirections et codes de sortie », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : Pipes, redirections et codes de sortie","langage":"Bash","contenu":"npm run check > verification.txt       # écrire la sortie dans un fichier\ncat package.json | grep \"scripts\"    # envoyer la sortie de cat à grep\nmkdir build && cd build                 # cd seulement si mkdir réussit\nnode app.js || echo \"Le serveur a échoué\" # action si erreur","legende":"Leçon « Pipes, redirections et codes de sortie ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Pipes, redirections et codes de sortie » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Pipes, redirections et codes de sortie » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Pipes, redirections et codes de sortie » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["shell-grep-rg-find","shell-terminal","npm-cli-scripts"]'::jsonb, 78);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-permissions', 'shell', 'Système', 'Permissions et exécution d’un script', 'Comprendre pourquoi un fichier ne peut pas être exécuté et utiliser chmod avec mesure.', '["chmod","permission","exécutable","./"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Créer et exécuter un script","langage":"Bash","contenu":"printf ''#!/usr/bin/env bash\\necho \"Bonjour\"\\n'' > bonjour.sh\nchmod +x bonjour.sh\n./bonjour.sh","legende":"Le shebang choisit l’interpréteur ; chmod +x ajoute le droit d’exécution pour le propriétaire, le groupe et les autres."},{"type":"decomposition","titre":"Pourquoi ./bonjour.sh ?","elements":[{"terme":"./","explication":"indique explicitement le dossier courant. Pour des raisons de sécurité, il n’est pas toujours dans PATH."},{"terme":"chmod +x","explication":"modifie les permissions pour rendre le fichier exécutable."},{"terme":"permission denied","explication":"le système refuse l’exécution car le droit x manque ou le dossier n’est pas accessible."}]},{"type":"alerte","variante":"attention","titre":"Éviter chmod 777","contenu":"Donner tous les droits à tout le monde masque le problème et augmente les risques. Accorder seulement le droit nécessaire."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"GNU Coreutils — chmod","url":"https://www.gnu.org/software/coreutils/manual/html_node/chmod-invocation.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Permissions et exécution d’un script », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : Permissions et exécution d’un script","langage":"Bash","contenu":"printf ''#!/usr/bin/env bash\\necho \"Bonjour\"\\n'' > bonjour.sh\nchmod +x bonjour.sh\n./bonjour.sh","legende":"Leçon « Permissions et exécution d’un script ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Permissions et exécution d’un script » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Permissions et exécution d’un script » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Permissions et exécution d’un script » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["shell-terminal","node-cli-check-watch"]'::jsonb, 79);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-curl', 'shell', 'HTTP', 'curl : tester une URL ou une API', 'Envoyer une requête HTTP depuis le terminal pour vérifier un serveur sans interface graphique.', '["curl","http","api","get","post","json"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Requêtes utiles","langage":"Bash","contenu":"curl http://localhost:3000/api/sante\ncurl -i https://example.com             # inclure les en-têtes HTTP\ncurl -X POST http://localhost:3000/api/notes \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"titre\":\"Lire curl\"}''","legende":"La barre inversée permet de continuer la commande sur la ligne suivante dans Bash."},{"type":"decomposition","titre":"Décomposition d’une requête POST","elements":[{"terme":"-X POST","explication":"choisit la méthode HTTP ; curl utilise GET par défaut."},{"terme":"-H","explication":"ajoute un en-tête, ici le type des données envoyées."},{"terme":"-d","explication":"envoie le corps de la requête, ici une chaîne JSON."},{"terme":"URL","explication":"adresse du serveur et du chemin API à tester."}]},{"type":"alerte","variante":"erreur","titre":"Serveur inaccessible","contenu":"ECONNREFUSED signifie souvent qu’aucun processus n’écoute sur le port. Lancez le serveur puis vérifiez le port et l’URL."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"curl — documentation","url":"https://curl.se/docs/"},{"label":"MDN — HTTP","url":"https://developer.mozilla.org/fr/docs/Web/HTTP"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « curl : tester une URL ou une API », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : curl : tester une URL ou une API","langage":"Bash","contenu":"curl http://localhost:3000/api/sante\ncurl -i https://example.com             # inclure les en-têtes HTTP\ncurl -X POST http://localhost:3000/api/notes \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"titre\":\"Lire curl\"}''","legende":"Leçon « curl : tester une URL ou une API ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « curl : tester une URL ou une API » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « curl : tester une URL ou une API » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « curl : tester une URL ou une API » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["http-requete-reponse","http-methodes","express-routes"]'::jsonb, 80);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('shell-env-path', 'shell', 'Environnement', 'Variables d’environnement et PATH', 'Comprendre comment le shell trouve node, npm et vos autres programmes.', '["env","PATH","export","variables","process.env"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Inspecter et définir","langage":"Bash","contenu":"echo \"$PATH\"                    # Dossiers parcourus pour trouver une commande\nwhich node                       # Chemin du programme utilisé\nNODE_ENV=development node app.js # Variable pour une seule commande\nexport PORT=3000                 # Variable disponible aux commandes suivantes\necho \"$PORT\"","legende":""},{"type":"texte","titre":"Lien avec Node.js","contenu":"Dans Node, process.env.PORT lit la variable PORT fournie par le système. Cela évite d’écrire un secret ou un port directement dans le code. Les fichiers .env sont pratiques, mais ne doivent pas être commités s’ils contiennent des secrets."},{"type":"alerte","variante":"attention","titre":"Ne jamais publier les secrets","contenu":"Ajoutez .env à .gitignore et fournissez un fichier .env.example sans valeur secrète pour expliquer les variables attendues."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"Node.js — process.env","url":"https://nodejs.org/api/process.html#processenv"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Le shell compose de petites commandes. Une commande fiable connaît son dossier, distingue sa sortie de ses erreurs et transmet un code retour à la CI."},{"type":"liste","titre":"Concepts à retenir","contenu":["chemin courant : cherchez où ce concept apparaît dans cette fiche avant de continuer.","sortie standard : cherchez où ce concept apparaît dans cette fiche avant de continuer.","pipeline : cherchez où ce concept apparaît dans cette fiche avant de continuer.","code retour : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Recherche","pwd, rg et sortie limitée","Le périmètre est visible."],["CI","Mode strict et codes retour","Une étape échoue au bon endroit."],["Chemin utilisateur","Quoter les variables","Les espaces ne cassent pas la commande."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Bash","contenu":"#!/usr/bin/env bash\nset -euo pipefail\n\nracine=\"$1\"\nprintf \"Analyse de : %s\\n\" \"$racine\"\nrg -n --glob \"*.js\" \"TODO|FIXME\" \"$racine\" || true","legende":"Exercice : passez un chemin avec des espaces et comparez absence de résultat et erreur."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « Variables d’environnement et PATH », partez de un argument ou une variable d’environnement texte. Produisez stdout, stderr et code retour cohérents. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un chemin avec espaces ou une variable manquante. La décision à justifier est la suivante : quoter les chemins et échouer tôt."},{"type":"code","titre":"Mini-exercice spécifique : Variables d’environnement et PATH","langage":"Bash","contenu":"echo \"$PATH\"                    # Dossiers parcourus pour trouver une commande\nwhich node                       # Chemin du programme utilisé\nNODE_ENV=development node app.js # Variable pour une seule commande\nexport PORT=3000                 # Variable disponible aux commandes suivantes\necho \"$PORT\"","legende":"Leçon « Variables d’environnement et PATH ». Entrée : un argument ou une variable d’environnement texte. Sortie attendue : stdout, stderr et code retour cohérents. Cas limite : un chemin avec espaces ou une variable manquante. Décision : quoter les chemins et échouer tôt."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « Variables d’environnement et PATH » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Travaillez dans un dossier explicite, affichez les chemins avant les actions et préférez les commandes composables aux commandes opaques."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « Variables d’environnement et PATH » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « Variables d’environnement et PATH » et la reformuler avec vos mots.","concepts":["chemin courant","sortie standard"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Recherche","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["node-process","node-runtime","git-cycle"]'::jsonb, 81);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('node-cli-check-watch', 'node', 'Commandes', 'node : vérifier, exécuter et surveiller', 'Utiliser la CLI Node.js pour connaître sa version, lancer un fichier et détecter les changements.', '["node --version","node --check","node --watch","cli"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Commandes Node.js","langage":"Bash","contenu":"node --version       # Version installée\nnpm --version        # Version de npm\nnode app.js          # Exécuter le fichier\nnode --check app.js  # Vérifier la syntaxe sans lancer le programme\nnode --watch app.js  # Relancer quand le fichier change\nnode                 # Ouvrir le REPL interactif","legende":""},{"type":"decomposition","titre":"Deux commandes souvent confondues","elements":[{"terme":"node app.js","explication":"charge et exécute réellement le programme ; ses effets peuvent se produire."},{"terme":"node --check app.js","explication":"analyse la syntaxe seulement ; une erreur logique ne sera pas détectée."},{"terme":"node --watch app.js","explication":"redémarre le processus lorsque les fichiers suivis changent ; pratique en développement."}]},{"type":"alerte","variante":"erreur","titre":"Version trop ancienne","contenu":"Une option peut manquer selon la version de Node. Utilisez une version LTS récente et vérifiez node --version."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"Node.js — options CLI","url":"https://nodejs.org/api/cli.html"}]},{"type":"texte","titre":"Explication approfondie","contenu":"Node.js exécute JavaScript dans un processus qui dialogue avec le système : fichiers, réseau et processus enfants. Chaque opération doit signaler sa fin ou son échec."},{"type":"liste","titre":"Concepts à retenir","contenu":["runtime : cherchez où ce concept apparaît dans cette fiche avant de continuer.","I/O : cherchez où ce concept apparaît dans cette fiche avant de continuer.","processus : cherchez où ce concept apparaît dans cette fiche avant de continuer.","erreurs système : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Petit fichier","API promise","Le code est court pour une donnée raisonnable."],["Gros fichier","Stream et backpressure","La mémoire reste stable."],["Commande serveur","Validation et journalisation sans secret","Le processus reste observable et sûr."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"Node.js","contenu":"const { readFile } = require(\"node:fs/promises\");\n\nasync function chargerConfiguration() {\n  try {\n    return JSON.parse(await readFile(\"./config.json\", \"utf8\"));\n  } catch (erreur) {\n    throw new Error(\"Configuration illisible\", { cause: erreur });\n  }\n}","legende":"Exercice : simulez un fichier absent et écrivez un message public utile."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Sur le serveur, toute donnée reçue est inconnue jusqu’à validation. Séparez le transport HTTP, la validation, la logique métier et la persistance : cela évite de mettre directement req.body en base ou de renvoyer une erreur interne au client."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Décrire un contrat d’entrée : champs obligatoires, types, tailles, autorisation et format de réponse attendu."},{"terme":"Valider","explication":"Parser JSON et contrôler les champs avec une règle côté serveur. Refuser tôt avec 400 si le client peut corriger."},{"terme":"Transformer","explication":"Convertir le DTO HTTP en modèle métier : normaliser un email, calculer une valeur et retirer les champs interdits."},{"terme":"Transmettre","explication":"Répondre avec le bon statut, Content-Type et une forme stable. Ne pas exposer stack, SQL, token ou chemin interne."},{"terme":"Stocker","explication":"Utiliser des requêtes paramétrées, des contraintes de base et une transaction lorsque plusieurs écritures doivent réussir ensemble."},{"terme":"Observer","explication":"Journaliser un identifiant de requête, la durée et la classe d’erreur sans journaliser les mots de passe ou tokens."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Entrée JSON publique","unknown puis schéma validé","HTTP JSON avec 400/422 en cas d’erreur","Limiter taille et débit, puis journaliser sans contenu sensible."],["Donnée authentifiée","DTO validé + utilisateur issu de la session","HTTP avec contrôle d’autorisation","L’identité ne doit pas venir d’un champ modifiable du corps."],["Écriture multi-table","Modèle métier et transaction","201 seulement après commit","Éviter les états partiellement écrits et prévoir l’idempotence."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « node : vérifier, exécuter et surveiller », partez de un fichier, argument ou résultat réseau. Produisez une donnée traitée sans bloquer inutilement le processus. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez un fichier absent ou beaucoup plus grand que prévu. La décision à justifier est la suivante : choisir API promise ou stream selon la mémoire disponible."},{"type":"code","titre":"Mini-exercice spécifique : node : vérifier, exécuter et surveiller","langage":"Bash","contenu":"node --version       # Version installée\nnpm --version        # Version de npm\nnode app.js          # Exécuter le fichier\nnode --check app.js  # Vérifier la syntaxe sans lancer le programme\nnode --watch app.js  # Relancer quand le fichier change\nnode                 # Ouvrir le REPL interactif","legende":"Leçon « node : vérifier, exécuter et surveiller ». Entrée : un fichier, argument ou résultat réseau. Sortie attendue : une donnée traitée sans bloquer inutilement le processus. Cas limite : un fichier absent ou beaucoup plus grand que prévu. Décision : choisir API promise ou stream selon la mémoire disponible."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « node : vérifier, exécuter et surveiller » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Vérifiez toujours le chemin courant, les erreurs système et la fin réelle de l’opération avant de considérer un script terminé."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « node : vérifier, exécuter et surveiller » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « node : vérifier, exécuter et surveiller » et la reformuler avec vos mots.","concepts":["runtime","I/O"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Petit fichier","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Entrée JSON publique","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"Donnée authentifiée","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["node-runtime","npm-cli-scripts","shell-permissions"]'::jsonb, 82);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('npm-init-install', 'npm', 'Démarrage', 'npm init et npm install : préparer un projet', 'Créer package.json, installer un package et distinguer dépendance d’exécution et outil de développement.', '["npm init","npm install","dependencies","devDependencies","package.json"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Initialiser puis installer","langage":"Bash","contenu":"mkdir mon-projet && cd mon-projet\nnpm init -y\nnpm install express\nnpm install --save-dev nodemon\nnpm install lodash@4.17.21","legende":"npm init -y crée un package.json avec des réponses par défaut. Les installations mettent à jour package.json et package-lock.json."},{"type":"decomposition","titre":"Où va chaque package ?","elements":[{"terme":"npm install express","explication":"ajoute express dans dependencies : le code en a besoin pour fonctionner."},{"terme":"npm install --save-dev nodemon","explication":"ajoute nodemon dans devDependencies : il aide pendant le développement."},{"terme":"package-lock.json","explication":"fige l’arbre exact des versions installées pour reproduire l’installation."}]},{"type":"comparaison","titre":"dependencies ou devDependencies ?","colonnes":["Question","dependencies","devDependencies"],"lignes":[["Nécessaire en production ?","Oui","Non, généralement"],["Exemples","express, zod","nodemon, eslint"],["Commande","npm install package","npm install -D outil"]]},{"type":"alerte","variante":"bonne-pratique","titre":"Bon réflexe","contenu":"Commitez package.json et package-lock.json. Ne commitez pas node_modules : il est régénéré avec npm ci ou npm install."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"npm — install","url":"https://docs.npmjs.com/cli/install/"},{"label":"npm — package.json","url":"https://docs.npmjs.com/cli/v11/configuring-npm/package-json"}]},{"type":"texte","titre":"Explication approfondie","contenu":"npm décrit comment installer et exécuter un projet JavaScript. package.json explique l’intention ; le lockfile fixe l’arbre réel des dépendances."},{"type":"liste","titre":"Concepts à retenir","contenu":["package.json : cherchez où ce concept apparaît dans cette fiche avant de continuer.","scripts : cherchez où ce concept apparaît dans cette fiche avant de continuer.","lockfile : cherchez où ce concept apparaît dans cette fiche avant de continuer.","semver : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Application","Committer le lockfile et utiliser npm ci","L’installation est reproductible."],["Bibliothèque","Dependencies pour les paquets d’exécution","Le consommateur reçoit le nécessaire."],["Outil ponctuel","npx ou script local","On évite une installation globale non versionnée."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JSON","contenu":"{\n  \"scripts\": {\n    \"check\": \"node --check src/index.js\",\n    \"test\": \"node --test\",\n    \"start\": \"node src/server.js\"\n  },\n  \"engines\": { \"node\": \">=20\" }\n}","legende":"Exercice : ajoutez un script de qualité et lancez-le depuis une machine neuve."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « npm init et npm install : préparer un projet », partez de un package.json et un environnement neuf. Produisez une commande reproductible. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez une version incompatible ou un lockfile absent. La décision à justifier est la suivante : versionner le contrat et vérifier la commande en CI."},{"type":"code","titre":"Mini-exercice spécifique : npm init et npm install : préparer un projet","langage":"Bash","contenu":"mkdir mon-projet && cd mon-projet\nnpm init -y\nnpm install express\nnpm install --save-dev nodemon\nnpm install lodash@4.17.21","legende":"Leçon « npm init et npm install : préparer un projet ». Entrée : un package.json et un environnement neuf. Sortie attendue : une commande reproductible. Cas limite : une version incompatible ou un lockfile absent. Décision : versionner le contrat et vérifier la commande en CI."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « npm init et npm install : préparer un projet » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Une commande reproductible et un lockfile relu valent mieux qu’une installation globale impossible à expliquer quelques semaines plus tard."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « npm init et npm install : préparer un projet » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « npm init et npm install : préparer un projet » et la reformuler avec vos mots.","concepts":["package.json","scripts"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Application","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["npm-cli-scripts","npm-ci-lockfile","node-cli-check-watch"]'::jsonb, 83);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('npm-cli-scripts', 'npm', 'Workflow', 'npm scripts et npx : lancer les outils du projet', 'Créer des commandes courtes et reproductibles dans package.json sans dépendre d’installations globales.', '["scripts","npm run","npx","exec","nodemon"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"package.json puis exécution","langage":"JSON","contenu":"\"scripts\": {\n  \"dev\": \"nodemon server.js\",\n  \"start\": \"node server.js\",\n  \"check\": \"node --check server.js\"\n}","legende":"Les commentaires ne sont pas autorisés dans JSON ; cette légende explique le rôle de chaque script."},{"type":"code","titre":"Commandes correspondantes","langage":"Bash","contenu":"npm run dev\nnpm start\nnpm run check\nnpm exec nodemon server.js\nnpx cowsay \"outil ponctuel\"","legende":"npm start est un raccourci pour le script start. npx / npm exec exécute un binaire fourni par un package."},{"type":"decomposition","titre":"Pourquoi les scripts sont utiles","elements":[{"terme":"nom stable","explication":"toute l’équipe tape npm run check au lieu de mémoriser une longue commande."},{"terme":"PATH local","explication":"npm ajoute node_modules/.bin, donc la version du projet est utilisée."},{"terme":"npx","explication":"lance un binaire local ou, si nécessaire, une version temporaire ; vérifiez toujours le package utilisé."}]},{"type":"alerte","variante":"erreur","titre":"Script inconnu","contenu":"npm ERR! Missing script: dev signifie que dev n’existe pas dans package.json ou que vous n’êtes pas dans le bon dossier."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"npm — scripts","url":"https://docs.npmjs.com/cli/v11/using-npm/scripts"},{"label":"npm — exec","url":"https://docs.npmjs.com/cli/npm-exec/"}]},{"type":"texte","titre":"Explication approfondie","contenu":"npm décrit comment installer et exécuter un projet JavaScript. package.json explique l’intention ; le lockfile fixe l’arbre réel des dépendances."},{"type":"liste","titre":"Concepts à retenir","contenu":["package.json : cherchez où ce concept apparaît dans cette fiche avant de continuer.","scripts : cherchez où ce concept apparaît dans cette fiche avant de continuer.","lockfile : cherchez où ce concept apparaît dans cette fiche avant de continuer.","semver : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Application","Committer le lockfile et utiliser npm ci","L’installation est reproductible."],["Bibliothèque","Dependencies pour les paquets d’exécution","Le consommateur reçoit le nécessaire."],["Outil ponctuel","npx ou script local","On évite une installation globale non versionnée."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JSON","contenu":"{\n  \"scripts\": {\n    \"check\": \"node --check src/index.js\",\n    \"test\": \"node --test\",\n    \"start\": \"node src/server.js\"\n  },\n  \"engines\": { \"node\": \">=20\" }\n}","legende":"Exercice : ajoutez un script de qualité et lancez-le depuis une machine neuve."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « npm scripts et npx : lancer les outils du projet », partez de un package.json et un environnement neuf. Produisez une commande reproductible. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez une version incompatible ou un lockfile absent. La décision à justifier est la suivante : versionner le contrat et vérifier la commande en CI."},{"type":"code","titre":"Mini-exercice spécifique : npm scripts et npx : lancer les outils du projet","langage":"JSON","contenu":"\"scripts\": {\n  \"dev\": \"nodemon server.js\",\n  \"start\": \"node server.js\",\n  \"check\": \"node --check server.js\"\n}","legende":"Leçon « npm scripts et npx : lancer les outils du projet ». Entrée : un package.json et un environnement neuf. Sortie attendue : une commande reproductible. Cas limite : une version incompatible ou un lockfile absent. Décision : versionner le contrat et vérifier la commande en CI."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « npm scripts et npx : lancer les outils du projet » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Une commande reproductible et un lockfile relu valent mieux qu’une installation globale impossible à expliquer quelques semaines plus tard."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « npm scripts et npx : lancer les outils du projet » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « npm scripts et npx : lancer les outils du projet » et la reformuler avec vos mots.","concepts":["package.json","scripts"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Application","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[11]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[17]}]'::jsonb, '["npm-init-install","npm-ci-lockfile","node-cli-check-watch"]'::jsonb, 84);
insert into public.bibliolearn_lessons (id, domain_id, category, title, summary, tags, level, sections, sessions, related_ids, sort_order) values ('npm-ci-lockfile', 'npm', 'Reproductibilité', 'npm ci, package-lock et installation propre', 'Installer exactement les versions verrouillées, notamment en CI ou lors d’un déploiement.', '["npm ci","lockfile","ci","node_modules"]'::jsonb, 'Fondamental', '[{"type":"code","titre":"Installation reproductible","langage":"Bash","contenu":"git clone https://github.com/exemple/projet.git\ncd projet\nnpm ci\nnpm run check\nnpm start","legende":"npm ci part d’un package-lock.json existant et installe un arbre propre. Il échoue si package.json et le lockfile ne correspondent pas."},{"type":"comparaison","titre":"npm install ou npm ci ?","colonnes":["Situation","npm install","npm ci"],"lignes":[["Développement quotidien","Peut mettre à jour le lockfile","Possible mais plus strict"],["CI / déploiement","Moins prévisible","Recommandé"],["node_modules existant","Le réutilise souvent","Le supprime puis repart du lockfile"]]},{"type":"alerte","variante":"erreur","titre":"Pas de lockfile","contenu":"npm ci nécessite package-lock.json (ou un lockfile compatible). Lancez npm install une première fois puis committez le fichier."},{"type":"liens","titre":"Documentation officielle","elements":[{"label":"npm — ci","url":"https://docs.npmjs.com/cli/commands/npm-ci/"}]},{"type":"texte","titre":"Explication approfondie","contenu":"npm décrit comment installer et exécuter un projet JavaScript. package.json explique l’intention ; le lockfile fixe l’arbre réel des dépendances."},{"type":"liste","titre":"Concepts à retenir","contenu":["package.json : cherchez où ce concept apparaît dans cette fiche avant de continuer.","scripts : cherchez où ce concept apparaît dans cette fiche avant de continuer.","lockfile : cherchez où ce concept apparaît dans cette fiche avant de continuer.","semver : cherchez où ce concept apparaît dans cette fiche avant de continuer."]},{"type":"comparaison","titre":"Scénarios et décisions","colonnes":["Scénario","Décision conseillée","Pourquoi"],"lignes":[["Application","Committer le lockfile et utiliser npm ci","L’installation est reproductible."],["Bibliothèque","Dependencies pour les paquets d’exécution","Le consommateur reçoit le nécessaire."],["Outil ponctuel","npx ou script local","On évite une installation globale non versionnée."]]},{"type":"code","titre":"Mini-exercice de logique","langage":"JSON","contenu":"{\n  \"scripts\": {\n    \"check\": \"node --check src/index.js\",\n    \"test\": \"node --test\",\n    \"start\": \"node src/server.js\"\n  },\n  \"engines\": { \"node\": \">=20\" }\n}","legende":"Exercice : ajoutez un script de qualité et lancez-le depuis une machine neuve."},{"type":"texte","titre":"Savoir transmettre la donnée","contenu":"Dans les outils et la CI, les données arrivent souvent sous forme de chaînes : arguments, variables d’environnement, fichiers et sorties de commandes. Parsez-les au bord du système, échouez tôt et ne mettez jamais un secret dans une sortie ou un commit."},{"type":"decomposition","titre":"Cycle de la donnée","elements":[{"terme":"Demander","explication":"Définir arguments, variables obligatoires, fichiers attendus et code retour avant de lancer le script."},{"terme":"Valider","explication":"Vérifier que le chemin existe, que le nombre est réellement un nombre et que les variables sensibles ne sont pas vides."},{"terme":"Transformer","explication":"Parser une chaîne vers le type utile, normaliser un chemin avec l’outil adapté et convertir un JSON seulement après contrôle."},{"terme":"Transmettre","explication":"Utiliser stdout pour le résultat, stderr pour le diagnostic et un code retour non nul pour l’échec."},{"terme":"Stocker","explication":"Conserver les secrets dans le gestionnaire de secrets de la CI, jamais dans .env commité, un log ou une commande copiée."},{"terme":"Observer","explication":"Afficher le contexte non sensible, la durée et l’étape en échec pour rendre le script dépannable."}]},{"type":"comparaison","titre":"Formats, transport et sécurité","colonnes":["Scénario","Type de donnée","Transmission","Contrôle"],"lignes":[["Commande locale","Arguments texte vérifiés","stdout, stderr et exit code","Éviter les chemins implicites et les variables non quotées."],["CI/CD","Variables injectées et types parsés","Logs masqués et artefact contrôlé","Utiliser secrets de plateforme et permissions minimales."],["Configuration serveur","JSON ou env validé au démarrage","Processus qui échoue tôt","Ne pas démarrer avec une configuration partiellement valide."]]},{"type":"texte","titre":"Consigne personnalisée","contenu":"Dans « npm ci, package-lock et installation propre », partez de un package.json et un environnement neuf. Produisez une commande reproductible. Avant de coder, écrivez le type reçu et le type attendu ; après le premier résultat, vérifiez une version incompatible ou un lockfile absent. La décision à justifier est la suivante : versionner le contrat et vérifier la commande en CI."},{"type":"code","titre":"Mini-exercice spécifique : npm ci, package-lock et installation propre","langage":"Bash","contenu":"git clone https://github.com/exemple/projet.git\ncd projet\nnpm ci\nnpm run check\nnpm start","legende":"Leçon « npm ci, package-lock et installation propre ». Entrée : un package.json et un environnement neuf. Sortie attendue : une commande reproductible. Cas limite : une version incompatible ou un lockfile absent. Décision : versionner le contrat et vérifier la commande en CI."},{"type":"liste","titre":"Questions avant de transmettre","contenu":["Quelle donnée est réellement nécessaire, et quelle donnée peut être supprimée ?","Qui produit la donnée, qui la reçoit et qui a le droit de la lire ou de la modifier ?","Quel type, format, encodage et taille maximale le contrat impose-t-il ?","À quelle frontière faut-il valider, convertir, journaliser ou refuser ?","Comment signaler succès, absence, erreur, donnée périmée ou accès interdit ?"]},{"type":"texte","titre":"Exercice de transfert (25 min)","contenu":"Reprenez l’idée de « npm ci, package-lock et installation propre » dans un petit dossier isolé. Dessinez le trajet de la donnée : source, type reçu, validation, transformation, transport, stockage éventuel, réponse et affichage. Testez un cas normal, une entrée vide ou invalide et une entrée plus grande que prévu. Notez l’observation, la décision prise et ce que vous changeriez si le projet passait en production."},{"type":"texte","titre":"Mise en situation","contenu":"Une commande reproductible et un lockfile relu valent mieux qu’une installation globale impossible à expliquer quelques semaines plus tard."},{"type":"alerte","variante":"retenir","titre":"Question de contrôle","contenu":"Pouvez-vous expliquer ce qui change si l’entrée est vide, invalide ou beaucoup plus grande dans « npm ci, package-lock et installation propre » ?"}]'::jsonb, '[{"id":"comprendre","titre":"Comprendre l’idée","duree":"10 min","objectif":"Identifier l’idée centrale de « npm ci, package-lock et installation propre » et la reformuler avec vos mots.","concepts":["package.json","scripts"],"activite":"Lire la définition, puis expliquer le problème que cette notion résout.","scenario":"Application","sections":[0]},{"id":"vocabulaire","titre":"Installer le vocabulaire","duree":"15 min","objectif":"Relier les mots importants à une observation concrète dans le code ou l’interface.","concepts":["source","type","contrat"],"activite":"Identifier la source, le type attendu et la forme transmise.","scenario":"Commande locale","sections":[1]},{"id":"construire","titre":"Construire pas à pas","duree":"25 min","objectif":"Demander, valider, transformer et transmettre une donnée sans perdre son sens.","concepts":["demander","valider","transformer"],"activite":"Copier l’exemple, changer une entrée, observer la sortie et traiter l’erreur.","scenario":"Cas nominal","sections":[0]},{"id":"decider","titre":"Choisir selon le scénario","duree":"20 min","objectif":"Comparer type, transport, stockage et niveau de sécurité selon votre infrastructure.","concepts":["type","transport","sécurité"],"activite":"Lire la grille et écrire qui produit, qui reçoit et qui a le droit de lire.","scenario":"CI/CD","sections":[10]},{"id":"verifier","titre":"Vérifier et transférer","duree":"15 min","objectif":"Tester une donnée absente, invalide ou trop grande et formuler une règle réutilisable.","concepts":["stockage","erreur","transfert"],"activite":"Répondre à la question de contrôle puis dessiner le trajet de la donnée dans un autre projet.","scenario":"Entrée vide, lente ou invalide","sections":[16]}]'::jsonb, '["npm-init-install","npm-cli-scripts","git-cycle"]'::jsonb, 85);
