insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-cssPropriete-align-items-322', 'align-items', 'CSS', 'css', 'Débutant → junior', '[]'::jsonb, 'align-items contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.', 'align-items est une référence de css qui contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, align-items n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans une règle CSS, une couche @layer, un module CSS ou une feuille globale.","La bonne décision dépend du contexte. Une propriété permet de décrire l’affichage sans mélanger le style et les données métier. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter align-items comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["align-items peut contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.","Dans une architecture propre, align-items reste dans la couche CSS et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Une propriété permet de décrire l’affichage sans mélanger le style et les données métier.","L’utiliser donne un nom précis à la décision « align-items » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas augmenter la spécificité ou utiliser !important avant d’avoir compris la cascade et l’ordre des couches.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Les unités, l’héritage, le contexte de formatage et le support navigateur peuvent changer le résultat.","Ne jamais confondre l’exemple de align-items avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de align-items","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser align-items sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec align-items, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à align-items."}]'::jsonb, '["dans une règle CSS, une couche @layer, un module CSS ou une feuille globale","Créer un module ou une règle nommée pour align-items, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si align-items touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["longueur","couleur","nombre","mot-clé","fonction CSS","valeur héritée"]'::jsonb, 'Entrée pour align-items → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence align-items dans une leçon","langage":"CSS","contenu":".barre-actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n}","explication":"Cet extrait vient de la leçon « Flexbox ». Il montre align-items dans un contexte réel du parcours ; adaptez les entrées, les erreurs et les droits avant de le réutiliser."}]'::jsonb, '{"duree":"20 min","objectif":"Maîtriser align-items dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, align-items doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de align-items avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de align-items fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : align-items","url":"https://developer.mozilla.org/fr/docs/Web/CSS/Reference/Properties"}]'::jsonb, 439);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-cssPropriete-align-self-323', 'align-self', 'CSS', 'css', 'Débutant → junior', '[]'::jsonb, 'align-self contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.', 'align-self est une référence de css qui contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, align-self n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans une règle CSS, une couche @layer, un module CSS ou une feuille globale.","La bonne décision dépend du contexte. Une propriété permet de décrire l’affichage sans mélanger le style et les données métier. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter align-self comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["align-self peut contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.","Dans une architecture propre, align-self reste dans la couche CSS et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Une propriété permet de décrire l’affichage sans mélanger le style et les données métier.","L’utiliser donne un nom précis à la décision « align-self » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas augmenter la spécificité ou utiliser !important avant d’avoir compris la cascade et l’ordre des couches.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Les unités, l’héritage, le contexte de formatage et le support navigateur peuvent changer le résultat.","Ne jamais confondre l’exemple de align-self avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de align-self","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser align-self sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec align-self, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à align-self."}]'::jsonb, '["dans une règle CSS, une couche @layer, un module CSS ou une feuille globale","Créer un module ou une règle nommée pour align-self, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si align-self touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["longueur","couleur","nombre","mot-clé","fonction CSS","valeur héritée"]'::jsonb, 'Entrée pour align-self → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Déclarer align-self","langage":"CSS","contenu":".card {\n  align-self: valeur;\n}","explication":"La propriété align-self modifie le rendu ou le comportement de layout. Tester la valeur, l’héritage, le fallback et la largeur d’écran qui vous intéressent."}]'::jsonb, '{"duree":"20 min","objectif":"Maîtriser align-self dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, align-self doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de align-self avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de align-self fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : align-self","url":"https://developer.mozilla.org/fr/docs/Web/CSS/Reference/Properties"}]'::jsonb, 440);
