insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-cssPropriete-translate-548', 'translate', 'CSS', 'css', 'Débutant → junior', '[]'::jsonb, 'translate contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.', 'translate est une référence de css qui contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, translate n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans une règle CSS, une couche @layer, un module CSS ou une feuille globale.","La bonne décision dépend du contexte. Une propriété permet de décrire l’affichage sans mélanger le style et les données métier. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter translate comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["translate peut contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.","Dans une architecture propre, translate reste dans la couche CSS et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Une propriété permet de décrire l’affichage sans mélanger le style et les données métier.","L’utiliser donne un nom précis à la décision « translate » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas augmenter la spécificité ou utiliser !important avant d’avoir compris la cascade et l’ordre des couches.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Les unités, l’héritage, le contexte de formatage et le support navigateur peuvent changer le résultat.","Ne jamais confondre l’exemple de translate avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de translate","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser translate sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec translate, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à translate."}]'::jsonb, '["dans une règle CSS, une couche @layer, un module CSS ou une feuille globale","Créer un module ou une règle nommée pour translate, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si translate touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["longueur","couleur","nombre","mot-clé","fonction CSS","valeur héritée"]'::jsonb, 'Entrée pour translate → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Déclarer translate","langage":"CSS","contenu":".card {\n  translate: valeur;\n}","explication":"La propriété translate modifie le rendu ou le comportement de layout. Tester la valeur, l’héritage, le fallback et la largeur d’écran qui vous intéressent."}]'::jsonb, '{"duree":"20 min","objectif":"Maîtriser translate dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, translate doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de translate avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de translate fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : translate","url":"https://developer.mozilla.org/fr/docs/Web/CSS/Reference/Properties"}]'::jsonb, 665);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-cssPropriete-unicode-bidi-549', 'unicode-bidi', 'CSS', 'css', 'Débutant → junior', '[]'::jsonb, 'unicode-bidi contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.', 'unicode-bidi est une référence de css qui contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, unicode-bidi n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans une règle CSS, une couche @layer, un module CSS ou une feuille globale.","La bonne décision dépend du contexte. Une propriété permet de décrire l’affichage sans mélanger le style et les données métier. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter unicode-bidi comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["unicode-bidi peut contrôle une dimension, une couleur, un layout, une animation ou un comportement de rendu.","Dans une architecture propre, unicode-bidi reste dans la couche CSS et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Une propriété permet de décrire l’affichage sans mélanger le style et les données métier.","L’utiliser donne un nom précis à la décision « unicode-bidi » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas augmenter la spécificité ou utiliser !important avant d’avoir compris la cascade et l’ordre des couches.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Les unités, l’héritage, le contexte de formatage et le support navigateur peuvent changer le résultat.","Ne jamais confondre l’exemple de unicode-bidi avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de unicode-bidi","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser unicode-bidi sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec unicode-bidi, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à unicode-bidi."}]'::jsonb, '["dans une règle CSS, une couche @layer, un module CSS ou une feuille globale","Créer un module ou une règle nommée pour unicode-bidi, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si unicode-bidi touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["longueur","couleur","nombre","mot-clé","fonction CSS","valeur héritée"]'::jsonb, 'Entrée pour unicode-bidi → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Déclarer unicode-bidi","langage":"CSS","contenu":".card {\n  unicode-bidi: valeur;\n}","explication":"La propriété unicode-bidi modifie le rendu ou le comportement de layout. Tester la valeur, l’héritage, le fallback et la largeur d’écran qui vous intéressent."}]'::jsonb, '{"duree":"20 min","objectif":"Maîtriser unicode-bidi dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, unicode-bidi doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de unicode-bidi avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de unicode-bidi fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : unicode-bidi","url":"https://developer.mozilla.org/fr/docs/Web/CSS/Reference/Properties"}]'::jsonb, 666);
