insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-cssSelecteur-hover-650', 'hover', 'CSS', 'css', 'Débutant → junior', '[]'::jsonb, 'hover cible un ensemble d’éléments avant d’appliquer des propriétés.', 'hover est une référence de css qui cible un ensemble d’éléments avant d’appliquer des propriétés. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, hover n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. à gauche d’une règle CSS ou dans querySelector selon le contexte.","La bonne décision dépend du contexte. Un sélecteur permet de limiter le style au bon périmètre. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter hover comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["hover peut cible un ensemble d’éléments avant d’appliquer des propriétés.","Dans une architecture propre, hover reste dans la couche CSS et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un sélecteur permet de limiter le style au bon périmètre.","L’utiliser donne un nom précis à la décision « hover » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas construire un sélecteur dépendant d’un chemin DOM fragile ou trop spécifique.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Un sélecteur large peut affecter des composants éloignés ; vérifier la spécificité et l’encapsulation.","Ne jamais confondre l’exemple de hover avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de hover","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser hover sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec hover, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à hover."}]'::jsonb, '["à gauche d’une règle CSS ou dans querySelector selon le contexte","Créer un module ou une règle nommée pour hover, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si hover touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["éléments","classes","attributs","pseudo-classes","pseudo-éléments"]'::jsonb, 'Entrée pour hover → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence hover dans une leçon","langage":"CSS","contenu":".carte {\n  border: 1px solid #334155;\n}\n\n.carte > h2 {\n  margin-block-start: 0;\n}\n\n.carte:hover {\n  border-color: #5eead4;\n}","explication":"Cet extrait vient de la leçon « Sélecteurs CSS et spécificité ». Il montre hover dans un contexte réel du parcours ; adaptez les entrées, les erreurs et les droits avant de le réutiliser."}]'::jsonb, '{"duree":"20 min","objectif":"Maîtriser hover dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, hover doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de hover avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de hover fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : hover","url":"https://developer.mozilla.org/fr/docs/Web/CSS/CSS_selectors"}]'::jsonb, 767);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-cssSelecteur-in-range-651', 'in-range', 'CSS', 'css', 'Débutant → junior', '[]'::jsonb, 'in-range cible un ensemble d’éléments avant d’appliquer des propriétés.', 'in-range est une référence de css qui cible un ensemble d’éléments avant d’appliquer des propriétés. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, in-range n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. à gauche d’une règle CSS ou dans querySelector selon le contexte.","La bonne décision dépend du contexte. Un sélecteur permet de limiter le style au bon périmètre. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter in-range comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["in-range peut cible un ensemble d’éléments avant d’appliquer des propriétés.","Dans une architecture propre, in-range reste dans la couche CSS et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un sélecteur permet de limiter le style au bon périmètre.","L’utiliser donne un nom précis à la décision « in-range » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas construire un sélecteur dépendant d’un chemin DOM fragile ou trop spécifique.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Un sélecteur large peut affecter des composants éloignés ; vérifier la spécificité et l’encapsulation.","Ne jamais confondre l’exemple de in-range avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de in-range","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser in-range sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec in-range, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à in-range."}]'::jsonb, '["à gauche d’une règle CSS ou dans querySelector selon le contexte","Créer un module ou une règle nommée pour in-range, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si in-range touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["éléments","classes","attributs","pseudo-classes","pseudo-éléments"]'::jsonb, 'Entrée pour in-range → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Cibler :in-range","langage":"CSS","contenu":"button:in-range {\n  outline: 2px solid currentColor;\n}","explication":"Le pseudo-sélecteur :in-range cible un état ou une partie du contenu. Vérifier qu’il ne remplace pas un état métier qui doit rester explicite."}]'::jsonb, '{"duree":"20 min","objectif":"Maîtriser in-range dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, in-range doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de in-range avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de in-range fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : in-range","url":"https://developer.mozilla.org/fr/docs/Web/CSS/CSS_selectors"}]'::jsonb, 768);
