insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-jsMotCle-keyof-767', 'keyof', 'JavaScript', 'javascript', 'Débutant → junior', '[]'::jsonb, 'keyof délimite une règle du langage : portée, contrôle, module, erreur ou asynchronisme.', 'keyof est une référence de javascript qui délimite une règle du langage : portée, contrôle, module, erreur ou asynchronisme. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, keyof n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans une expression, une déclaration ou un bloc de contrôle.","La bonne décision dépend du contexte. Comprendre le mot-clé explique ce que le moteur peut garantir avant même de regarder le framework. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter keyof comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["keyof peut délimite une règle du langage : portée, contrôle, module, erreur ou asynchronisme.","Dans une architecture propre, keyof reste dans la couche JavaScript et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Comprendre le mot-clé explique ce que le moteur peut garantir avant même de regarder le framework.","L’utiliser donne un nom précis à la décision « keyof » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas utiliser une construction moderne sans connaître sa portée, sa version cible et son comportement asynchrone.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["let, const, var, this, await et throw ne se remplacent pas mécaniquement.","Ne jamais confondre l’exemple de keyof avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de keyof","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser keyof sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec keyof, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à keyof."}]'::jsonb, '["dans une expression, une déclaration ou un bloc de contrôle","Créer un module ou une règle nommée pour keyof, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si keyof touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["valeur","bloc","fonction","module","exception"]'::jsonb, 'Entrée pour keyof → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Comprendre keyof","langage":"JavaScript","contenu":"keyof valeur;","explication":"Le mot-clé keyof modifie la structure ou l’exécution du programme. Le replacer dans une fonction testée et regarder sa portée réelle."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser keyof dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, keyof doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de keyof avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de keyof fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : keyof","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Reference/Statements"}]'::jsonb, 884);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-jsMotCle-readonly-768', 'readonly', 'JavaScript', 'javascript', 'Débutant → junior', '[]'::jsonb, 'readonly délimite une règle du langage : portée, contrôle, module, erreur ou asynchronisme.', 'readonly est une référence de javascript qui délimite une règle du langage : portée, contrôle, module, erreur ou asynchronisme. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, readonly n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans une expression, une déclaration ou un bloc de contrôle.","La bonne décision dépend du contexte. Comprendre le mot-clé explique ce que le moteur peut garantir avant même de regarder le framework. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter readonly comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["readonly peut délimite une règle du langage : portée, contrôle, module, erreur ou asynchronisme.","Dans une architecture propre, readonly reste dans la couche JavaScript et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Comprendre le mot-clé explique ce que le moteur peut garantir avant même de regarder le framework.","L’utiliser donne un nom précis à la décision « readonly » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas utiliser une construction moderne sans connaître sa portée, sa version cible et son comportement asynchrone.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["let, const, var, this, await et throw ne se remplacent pas mécaniquement.","Ne jamais confondre l’exemple de readonly avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de readonly","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser readonly sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec readonly, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à readonly."}]'::jsonb, '["dans une expression, une déclaration ou un bloc de contrôle","Créer un module ou une règle nommée pour readonly, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si readonly touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["valeur","bloc","fonction","module","exception"]'::jsonb, 'Entrée pour readonly → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Comprendre readonly","langage":"JavaScript","contenu":"readonly valeur;","explication":"Le mot-clé readonly modifie la structure ou l’exécution du programme. Le replacer dans une fonction testée et regarder sa portée réelle."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser readonly dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, readonly doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de readonly avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de readonly fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : readonly","url":"https://developer.mozilla.org/fr/docs/Web/JavaScript/Reference/Statements"}]'::jsonb, 885);
