insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-nodeApi-node-https-1076', 'node:https', 'Node.js', 'node', 'Débutant → junior', '[]'::jsonb, 'node:https donne au serveur accès aux fichiers, processus, réseau, crypto ou flux.', 'node:https est une référence de node.js qui donne au serveur accès aux fichiers, processus, réseau, crypto ou flux. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, node:https n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans un service backend, un script CLI, un worker ou une route serveur.","La bonne décision dépend du contexte. L’API Node relie la logique JavaScript aux ressources de la machine. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter node:https comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["node:https peut donne au serveur accès aux fichiers, processus, réseau, crypto ou flux.","Dans une architecture propre, node:https reste dans la couche Node.js et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["L’API Node relie la logique JavaScript aux ressources de la machine.","L’utiliser donne un nom précis à la décision « node:https » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas bloquer la boucle d’événements ni traiter une donnée distante comme un chemin sûr.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Les accès fichier, processus et réseau ont des permissions et doivent être observables.","Ne jamais confondre l’exemple de node:https avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de node:https","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser node:https sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec node:https, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à node:https."}]'::jsonb, '["dans un service backend, un script CLI, un worker ou une route serveur","Créer un module ou une règle nommée pour node:https, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si node:https touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["Buffer","stream","Promise","socket","processus","fichier"]'::jsonb, 'Entrée pour node:https → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Importer node:https","langage":"JavaScript","contenu":"import { valeur } from ''node:https'';\n\nconst resultat = valeur();","explication":"node:https appartient à la plateforme Node.js. L’isoler derrière un service facilite les tests et évite de coupler toute l’application au système."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser node:https dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, node:https doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de node:https avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de node:https fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : node:https","url":"https://nodejs.org/api/"}]'::jsonb, 1193);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-nodeApi-node-module-1077', 'node:module', 'Node.js', 'node', 'Débutant → junior', '[]'::jsonb, 'node:module donne au serveur accès aux fichiers, processus, réseau, crypto ou flux.', 'node:module est une référence de node.js qui donne au serveur accès aux fichiers, processus, réseau, crypto ou flux. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, node:module n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans un service backend, un script CLI, un worker ou une route serveur.","La bonne décision dépend du contexte. L’API Node relie la logique JavaScript aux ressources de la machine. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter node:module comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["node:module peut donne au serveur accès aux fichiers, processus, réseau, crypto ou flux.","Dans une architecture propre, node:module reste dans la couche Node.js et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["L’API Node relie la logique JavaScript aux ressources de la machine.","L’utiliser donne un nom précis à la décision « node:module » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas bloquer la boucle d’événements ni traiter une donnée distante comme un chemin sûr.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Les accès fichier, processus et réseau ont des permissions et doivent être observables.","Ne jamais confondre l’exemple de node:module avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de node:module","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser node:module sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec node:module, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à node:module."}]'::jsonb, '["dans un service backend, un script CLI, un worker ou une route serveur","Créer un module ou une règle nommée pour node:module, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si node:module touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["Buffer","stream","Promise","socket","processus","fichier"]'::jsonb, 'Entrée pour node:module → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence node:module dans une leçon","langage":"Bash","contenu":"printf \"node_modules/\\n.env\\n.DS_Store\\n\" > .gitignore\ngit add .gitignore\ngit commit -m \"Ignorer les fichiers locaux\"","explication":"Cet extrait vient de la leçon « Cycle Git : init, status, add, commit, log ». Il montre node:module dans un contexte réel du parcours ; adaptez les entrées, les erreurs et les droits avant de le réutiliser."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser node:module dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, node:module doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de node:module avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de node:module fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : node:module","url":"https://nodejs.org/api/"}]'::jsonb, 1194);
