insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-docker-multi-stage-1288', 'multi-stage', 'Docker', 'docker', 'Débutant → junior', '[]'::jsonb, 'multi-stage décrit ou exécute un environnement reproductible pour un processus.', 'multi-stage est une référence de docker qui décrit ou exécute un environnement reproductible pour un processus. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, multi-stage n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans Dockerfile, compose.yaml, CI ou commande d’exploitation.","La bonne décision dépend du contexte. Docker réduit l’écart entre les environnements et rend les dépendances explicites. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter multi-stage comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["multi-stage peut décrit ou exécute un environnement reproductible pour un processus.","Dans une architecture propre, multi-stage reste dans la couche Docker et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Docker réduit l’écart entre les environnements et rend les dépendances explicites.","L’utiliser donne un nom précis à la décision « multi-stage » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas mettre des secrets dans une image ni utiliser un conteneur comme sauvegarde.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Une image n’est pas une isolation absolue ; scanner l’image, limiter les permissions et gérer le stockage.","Ne jamais confondre l’exemple de multi-stage avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de multi-stage","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser multi-stage sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec multi-stage, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à multi-stage."}]'::jsonb, '["dans Dockerfile, compose.yaml, CI ou commande d’exploitation","Créer un module ou une règle nommée pour multi-stage, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si multi-stage touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["image","conteneur","volume","réseau","layer","secret"]'::jsonb, 'Entrée pour multi-stage → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Configurer multi-stage","langage":"Dockerfile/Shell","contenu":"multi-stage node:22-alpine\n# construire, inspecter puis exécuter l’image","explication":"multi-stage intervient dans l’image ou le cycle de vie du conteneur. Ne pas embarquer de secret et vérifier le contexte de build."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser multi-stage dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, multi-stage doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de multi-stage avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de multi-stage fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : multi-stage","url":"https://docs.docker.com/reference/"}]'::jsonb, 1405);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-docker-build-context-1289', 'build context', 'Docker', 'docker', 'Débutant → junior', '[]'::jsonb, 'build context décrit ou exécute un environnement reproductible pour un processus.', 'build context est une référence de docker qui décrit ou exécute un environnement reproductible pour un processus. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, build context n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans Dockerfile, compose.yaml, CI ou commande d’exploitation.","La bonne décision dépend du contexte. Docker réduit l’écart entre les environnements et rend les dépendances explicites. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter build context comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["build context peut décrit ou exécute un environnement reproductible pour un processus.","Dans une architecture propre, build context reste dans la couche Docker et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Docker réduit l’écart entre les environnements et rend les dépendances explicites.","L’utiliser donne un nom précis à la décision « build context » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas mettre des secrets dans une image ni utiliser un conteneur comme sauvegarde.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Une image n’est pas une isolation absolue ; scanner l’image, limiter les permissions et gérer le stockage.","Ne jamais confondre l’exemple de build context avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de build context","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser build context sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec build context, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à build context."}]'::jsonb, '["dans Dockerfile, compose.yaml, CI ou commande d’exploitation","Créer un module ou une règle nommée pour build context, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si build context touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["image","conteneur","volume","réseau","layer","secret"]'::jsonb, 'Entrée pour build context → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Configurer build context","langage":"Dockerfile/Shell","contenu":"build context node:22-alpine\n# construire, inspecter puis exécuter l’image","explication":"build context intervient dans l’image ou le cycle de vie du conteneur. Ne pas embarquer de secret et vérifier le contexte de build."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser build context dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, build context doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de build context avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de build context fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : build context","url":"https://docs.docker.com/reference/"}]'::jsonb, 1406);
