insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-test-page-1683', 'page', 'Tests et qualité', 'tests', 'Débutant → junior', '[]'::jsonb, 'page vérifie un comportement attendu et rend une régression détectable.', 'page est une référence de tests et qualité qui vérifie un comportement attendu et rend une régression détectable. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, page n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans test, __tests__, e2e, CI ou une commande de qualité.","La bonne décision dépend du contexte. Un test précise ce que l’équipe veut conserver et accélère une refonte sûre. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter page comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["page peut vérifie un comportement attendu et rend une régression détectable.","Dans une architecture propre, page reste dans la couche Tests et qualité et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un test précise ce que l’équipe veut conserver et accélère une refonte sûre.","L’utiliser donne un nom précis à la décision « page » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas tester seulement l’implémentation interne ni rendre un test dépendant d’un réseau instable.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Un test vert ne couvre que le scénario décrit ; les données limites et les droits comptent.","Ne jamais confondre l’exemple de page avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de page","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser page sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec page, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à page."}]'::jsonb, '["dans test, __tests__, e2e, CI ou une commande de qualité","Créer un module ou une règle nommée pour page, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si page touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["entrée","résultat","assertion","fixture","mock","trace"]'::jsonb, 'Entrée pour page → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence page dans une leçon","langage":"HTML","contenu":"<!doctype html>\n<html lang=\"fr\">\n  <head>\n    <!-- Encodage des caractères et affichage mobile. -->\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <!-- Le titre apparaît dans l’onglet du navigateur. -->\n    <title>Titre de la page</title>\n  </head>\n  <body>\n    <!-- Le contenu visible commence ici. -->\n    <h1>Contenu principal</h1>\n  </body>\n</html>","explication":"Cet extrait vient de la leçon « Structure d’un document HTML ». Il montre page dans un contexte réel du parcours ; adaptez les entrées, les erreurs et les droits avant de le réutiliser."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser page dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, page doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de page avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de page fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : page","url":"https://vitest.dev/"}]'::jsonb, 1800);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-test-route-interception-1684', 'route interception', 'Tests et qualité', 'tests', 'Débutant → junior', '[]'::jsonb, 'route interception vérifie un comportement attendu et rend une régression détectable.', 'route interception est une référence de tests et qualité qui vérifie un comportement attendu et rend une régression détectable. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, route interception n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans test, __tests__, e2e, CI ou une commande de qualité.","La bonne décision dépend du contexte. Un test précise ce que l’équipe veut conserver et accélère une refonte sûre. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter route interception comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["route interception peut vérifie un comportement attendu et rend une régression détectable.","Dans une architecture propre, route interception reste dans la couche Tests et qualité et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un test précise ce que l’équipe veut conserver et accélère une refonte sûre.","L’utiliser donne un nom précis à la décision « route interception » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas tester seulement l’implémentation interne ni rendre un test dépendant d’un réseau instable.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Un test vert ne couvre que le scénario décrit ; les données limites et les droits comptent.","Ne jamais confondre l’exemple de route interception avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de route interception","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser route interception sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec route interception, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à route interception."}]'::jsonb, '["dans test, __tests__, e2e, CI ou une commande de qualité","Créer un module ou une règle nommée pour route interception, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si route interception touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["entrée","résultat","assertion","fixture","mock","trace"]'::jsonb, 'Entrée pour route interception → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Tester route interception","langage":"JavaScript","contenu":"it(''route interception respecte le contrat'', async () => {\n  const resultat = await action();\n  expect(resultat).toBeDefined();\n});","explication":"Un test sur route interception doit exprimer un comportement observable, un cas nominal et au moins un cas limite."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser route interception dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, route interception doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de route interception avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de route interception fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : route interception","url":"https://vitest.dev/"}]'::jsonb, 1801);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-test-trace-viewer-1685', 'trace viewer', 'Tests et qualité', 'tests', 'Débutant → junior', '[]'::jsonb, 'trace viewer vérifie un comportement attendu et rend une régression détectable.', 'trace viewer est une référence de tests et qualité qui vérifie un comportement attendu et rend une régression détectable. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, trace viewer n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans test, __tests__, e2e, CI ou une commande de qualité.","La bonne décision dépend du contexte. Un test précise ce que l’équipe veut conserver et accélère une refonte sûre. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter trace viewer comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["trace viewer peut vérifie un comportement attendu et rend une régression détectable.","Dans une architecture propre, trace viewer reste dans la couche Tests et qualité et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un test précise ce que l’équipe veut conserver et accélère une refonte sûre.","L’utiliser donne un nom précis à la décision « trace viewer » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas tester seulement l’implémentation interne ni rendre un test dépendant d’un réseau instable.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Un test vert ne couvre que le scénario décrit ; les données limites et les droits comptent.","Ne jamais confondre l’exemple de trace viewer avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de trace viewer","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser trace viewer sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec trace viewer, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à trace viewer."}]'::jsonb, '["dans test, __tests__, e2e, CI ou une commande de qualité","Créer un module ou une règle nommée pour trace viewer, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si trace viewer touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["entrée","résultat","assertion","fixture","mock","trace"]'::jsonb, 'Entrée pour trace viewer → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Tester trace viewer","langage":"JavaScript","contenu":"it(''trace viewer respecte le contrat'', async () => {\n  const resultat = await action();\n  expect(resultat).toBeDefined();\n});","explication":"Un test sur trace viewer doit exprimer un comportement observable, un cas nominal et au moins un cas limite."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser trace viewer dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, trace viewer doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de trace viewer avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de trace viewer fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : trace viewer","url":"https://vitest.dev/"}]'::jsonb, 1802);
