insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-outil-tree-shaking-1754', 'tree shaking', 'Outils et packages', 'outils', 'Débutant → junior', '[]'::jsonb, 'tree shaking automatise une étape de développement, de build, de contrôle ou de publication.', 'tree shaking est une référence de outils et packages qui automatise une étape de développement, de build, de contrôle ou de publication. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, tree shaking n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans package.json, lockfile, Makefile, CI, config ou terminal.","La bonne décision dépend du contexte. Un outil bien choisi rend une procédure reproductible par toute l’équipe. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter tree shaking comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["tree shaking peut automatise une étape de développement, de build, de contrôle ou de publication.","Dans une architecture propre, tree shaking reste dans la couche Outils et packages et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un outil bien choisi rend une procédure reproductible par toute l’équipe.","L’utiliser donne un nom précis à la décision « tree shaking » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas ajouter une dépendance sans regarder sa maintenance, sa licence, son poids et son alternative native.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Le package exécute du code dans la chaîne ; verrouiller la version et relire les scripts.","Ne jamais confondre l’exemple de tree shaking avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de tree shaking","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser tree shaking sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec tree shaking, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à tree shaking."}]'::jsonb, '["dans package.json, lockfile, Makefile, CI, config ou terminal","Créer un module ou une règle nommée pour tree shaking, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si tree shaking touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["package","commande","version","artefact","rapport","configuration"]'::jsonb, 'Entrée pour tree shaking → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence tree shaking","langage":"CLI/Configuration","contenu":"# tree shaking\n# vérifier l’aide officielle et le résultat obtenu","explication":"tree shaking est une référence de l’outillage. La bonne utilisation dépend de la version, du projet, des données et de l’environnement."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser tree shaking dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, tree shaking doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de tree shaking avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de tree shaking fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : tree shaking","url":"https://docs.npmjs.com/"}]'::jsonb, 1871);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-outil-code-splitting-1755', 'code splitting', 'Outils et packages', 'outils', 'Débutant → junior', '[]'::jsonb, 'code splitting automatise une étape de développement, de build, de contrôle ou de publication.', 'code splitting est une référence de outils et packages qui automatise une étape de développement, de build, de contrôle ou de publication. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, code splitting n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans package.json, lockfile, Makefile, CI, config ou terminal.","La bonne décision dépend du contexte. Un outil bien choisi rend une procédure reproductible par toute l’équipe. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter code splitting comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["code splitting peut automatise une étape de développement, de build, de contrôle ou de publication.","Dans une architecture propre, code splitting reste dans la couche Outils et packages et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un outil bien choisi rend une procédure reproductible par toute l’équipe.","L’utiliser donne un nom précis à la décision « code splitting » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas ajouter une dépendance sans regarder sa maintenance, sa licence, son poids et son alternative native.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Le package exécute du code dans la chaîne ; verrouiller la version et relire les scripts.","Ne jamais confondre l’exemple de code splitting avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de code splitting","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser code splitting sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec code splitting, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à code splitting."}]'::jsonb, '["dans package.json, lockfile, Makefile, CI, config ou terminal","Créer un module ou une règle nommée pour code splitting, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si code splitting touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["package","commande","version","artefact","rapport","configuration"]'::jsonb, 'Entrée pour code splitting → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence code splitting","langage":"CLI/Configuration","contenu":"# code splitting\n# vérifier l’aide officielle et le résultat obtenu","explication":"code splitting est une référence de l’outillage. La bonne utilisation dépend de la version, du projet, des données et de l’environnement."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser code splitting dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, code splitting doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de code splitting avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de code splitting fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : code splitting","url":"https://docs.npmjs.com/"}]'::jsonb, 1872);
insert into public.bibliolearn_library_entries (id, term, category, family, level, aliases, summary, definition, article, roles, why_use, avoid_when, warnings, scenarios, code_structure, data_types, data_cycle, examples, exercise, related_ids, links, sort_order) values ('ref-outil-lazy-loading-1756', 'lazy loading', 'Outils et packages', 'outils', 'Débutant → junior', '[]'::jsonb, 'lazy loading automatise une étape de développement, de build, de contrôle ou de publication.', 'lazy loading est une référence de outils et packages qui automatise une étape de développement, de build, de contrôle ou de publication. Pour l’utiliser correctement, il faut savoir quelle donnée elle reçoit, quel résultat elle produit et quelle couche reste responsable de la validation, de la sécurité et de l’observation.', '["Dans un projet réel, lazy loading n’est pas une ligne isolée : il intervient dans un contrat entre une entrée, une transformation et une sortie. dans package.json, lockfile, Makefile, CI, config ou terminal.","La bonne décision dépend du contexte. Un outil bien choisi rend une procédure reproductible par toute l’équipe. Commencer par un petit scénario permet de vérifier le résultat avant de l’introduire dans une abstraction plus large.","Si la donnée vient d’un utilisateur, d’un réseau ou d’une commande, traiter lazy loading comme une frontière : vérifier la forme, limiter la portée, observer l’échec et transmettre uniquement ce dont la couche suivante a besoin."]'::jsonb, '["lazy loading peut automatise une étape de développement, de build, de contrôle ou de publication.","Dans une architecture propre, lazy loading reste dans la couche Outils et packages et expose un résultat compréhensible par la couche suivante.","Lorsqu’il est utilisé dans un autre contexte, documenter explicitement l’adaptation plutôt que de laisser le comportement implicite."]'::jsonb, '["Un outil bien choisi rend une procédure reproductible par toute l’équipe.","L’utiliser donne un nom précis à la décision « lazy loading » et facilite la recherche dans le dépôt.","Son exemple peut être testé avec une entrée nominale, une donnée vide et une erreur attendue."]'::jsonb, '["Ne pas ajouter une dépendance sans regarder sa maintenance, sa licence, son poids et son alternative native.","Ne pas le choisir simplement parce qu’un tutoriel l’emploie : comparer la complexité, la compatibilité, le coût et la maintenance.","Si l’outil ou la syntaxe masque la donnée plutôt qu’elle ne l’explique, revenir à une structure plus explicite."]'::jsonb, '["Le package exécute du code dans la chaîne ; verrouiller la version et relire les scripts.","Ne jamais confondre l’exemple de lazy loading avec une règle d’autorisation ou une validation complète.","Lire la documentation de la version utilisée : les options, le runtime et les comportements par défaut peuvent évoluer."]'::jsonb, '[{"cas":"Premier usage de lazy loading","decision":"Commencer par l’exemple minimal et mesurer le résultat","pourquoi":"Le comportement est isolé avant d’être partagé.","application":"Utiliser lazy loading sur une donnée connue puis vérifier la valeur renvoyée."},{"cas":"Donnée réelle avec erreurs possibles","decision":"Ajouter validation, limite, traitement d’erreur et observation","pourquoi":"Une entrée externe ne doit pas casser le service ou exposer une information.","application":"Avec lazy loading, afficher ou journaliser une erreur utile sans révéler de secret."},{"cas":"Trafic ou équipe qui grandit","decision":"Documenter le contrat et automatiser un test","pourquoi":"Le comportement reste stable quand le contexte change.","application":"Conserver un scénario de régression dédié à lazy loading."}]'::jsonb, '["dans package.json, lockfile, Makefile, CI, config ou terminal","Créer un module ou une règle nommée pour lazy loading, puis transmettre des valeurs explicites plutôt qu’un état global caché.","Si lazy loading touche une frontière réseau, fichier, base ou déploiement, séparer l’adaptateur technique de la logique métier."]'::jsonb, '["package","commande","version","artefact","rapport","configuration"]'::jsonb, 'Entrée pour lazy loading → validation de forme et de droits → transformation minimale → résultat ou erreur → transmission → observation. La conversion doit être faite au bord de la couche qui en a besoin.', '[{"titre":"Référence lazy loading","langage":"CLI/Configuration","contenu":"# lazy loading\n# vérifier l’aide officielle et le résultat obtenu","explication":"lazy loading est une référence de l’outillage. La bonne utilisation dépend de la version, du projet, des données et de l’environnement."}]'::jsonb, '{"duree":"25 min","objectif":"Maîtriser lazy loading dans un scénario concret et expliquer la donnée avant et après son passage.","contexte":"Vous ajoutez une fonctionnalité au carnet de leçons. Une entrée arrive, lazy loading doit participer au traitement, puis le résultat doit être transmis sans perdre son sens.","etapes":["Reproduire l’exemple de lazy loading avec une donnée nominale et nommer la valeur importante.","Ajouter un cas vide ou incorrect ; expliquer la réponse au lieu de laisser une erreur silencieuse.","Identifier la couche qui valide, la couche qui transforme et la couche qui présente ou persiste le résultat.","Écrire une vérification : test, assertion, validation visuelle, log ou commande de contrôle."],"validation":["Le cas nominal de lazy loading fonctionne.","Le cas limite est compréhensible.","Aucune donnée sensible inutile ne traverse la frontière.","Le choix est documenté en une phrase pour un autre développeur."]}'::jsonb, '[]'::jsonb, '[{"label":"Documentation officielle : lazy loading","url":"https://docs.npmjs.com/"}]'::jsonb, 1873);
